window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3b479bd4856c1d4b"]={"versions": [{"id": "FIG-3b479bd4856c1d4b", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) zur Konfiguration des Diagnostic Communication Manager (DCM), spezifisch für den UDS-Dienst 0x27 (SecurityAccess). Das Diagramm definiert die BSW-Modulkonfigurationsstruktur (<code>ModuleDef</code>, <code>ParamConfContainerDef</code>, <code>FloatParamDef</code>, <code>IntegerParamDef</code>) innerhalb des Rahmens <code>class DcmDspSecurity</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Konfigurationshierarchie umfasst folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Dcm :ModuleDef</code> (Multiplizität 0..1) enthält über die Komposition <code>+container</code> den Container <code>DcmDsp :ParamConfContainerDef</code> (Multiplizität 1..1).\n</li><li><code>DcmDsp</code> aggregiert über <code>+subContainer</code> den Container <code>DcmDspSecurity :ParamConfContainerDef</code> (Multiplizität 1..1).\n</li><li><code>DcmDspSecurity</code> aggregiert über <code>+subContainer</code> 0 bis 31 Instanzen von <code>DcmDspSecurityRow :ParamConfContainerDef</code> (Multiplizität 0..31).\n</li><li><code>DcmDspSecurityRow</code> aggregiert über <code>+parameter</code> sieben Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>DcmDspSecurityLevel :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 0</code>, <code>max = 63</code>, <code>symbolicNameValue = true</code>).\n</li><li><code>DcmDspSecurityNumAttDelay :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 1</code>, <code>max = 255</code>).\n</li><li><code>DcmDspSecurityDelayTime :FloatParamDef</code> (Multiplizität 1..1, <code>min = 0</code>).\n</li><li><code>DcmDspSecurityDelayTimeOnBoot :FloatParamDef</code> (Multiplizität 1..1, <code>min = 0</code>).\n</li><li><code>DcmDspSecurityNumAttLock :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 0</code>, <code>max = 255</code>).\n</li><li><code>DcmDspSecuritySeedSize :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 1</code>, <code>max = 255</code>).\n</li><li><code>DcmDspSecurityKeySize :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 1</code>, <code>max = 255</code>).\n</li><li><code>DcmDspSecurityADRSize :IntegerParamDef</code> (Multiplizität 0..1, <code>min = 1</code>, <code>max = 255</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsdiagramm ohne dynamische Interaktions- oder Ablaufbeschreibungen. Es spezifiziert die Struktur und Wertebereiche für die Parametrierung der Sicherheitszugriffsstufen (Security Levels), Fehlversuchszähler, Sperrzeiten (Delay Times) und Schlüssel-/Seed-Längen zur Generierungs- bzw. Kompilierzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist normativ für DCM-Konfigurationsgeneratoren und XML-/ARXML-Beschreibungen. Jede Sicherheitsstufe (<code>DcmDspSecurityRow</code>) repräsentiert eine konkrete Sicherheitsstufe von UDS Service 0x27. Die Wertebereiche (<code>min</code>/<code>max</code>) und Multiplizitäten erzwingen eine strikte Validierung: Pro Sicherheitsstufe ist genau ein <code>DcmDspSecurityLevel</code> erforderlich, während <code>DcmDspSecurityADRSize</code> (Access Data Record Size) optional ist (Multiplizität 0..1).</p>"}, {"id": "FIG-73b1140926bd8522", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) zur Konfiguration des Diagnostic Communication Manager (DCM), spezifisch für den UDS-Dienst 0x27 (SecurityAccess). Das Diagramm definiert die BSW-Modulkonfigurationsstruktur (<code>ModuleDef</code>, <code>ParamConfContainerDef</code>, <code>FloatParamDef</code>, <code>IntegerParamDef</code>) für die Parametrierung der Security-Eigenschaften.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Konfigurationshierarchie umfasst folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Dcm :ModuleDef</code> (Multiplizität 0..1) enthält über die Komposition <code>+container</code> den Container <code>DcmConfigSet :ParamConfContainerDef</code> (Multiplizität 0..1, <code>multipleConfigurationContainer = true</code>).\n</li><li><code>DcmConfigSet</code> aggregiert über <code>+subContainer</code> den Container <code>DcmDsp :ParamConfContainerDef</code> (Multiplizität 1..1).\n</li><li><code>DcmDsp</code> aggregiert über <code>+subContainer</code> den Container <code>DcmDspSecurity :ParamConfContainerDef</code> (Multiplizität 1..1).\n</li><li><code>DcmDspSecurity</code> aggregiert über <code>+subContainer</code> 0 bis 31 Instanzen von <code>DcmDspSecurityRow :ParamConfContainerDef</code> (Multiplizität 0..31).\n</li><li><code>DcmDspSecurityRow</code> aggregiert über <code>+parameter</code> sieben Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>DcmDspSecurityLevel :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 1</code>, <code>max = 63</code>, <code>symbolicNameValue = true</code>).\n</li><li><code>DcmDspSecurityNumAttDelay :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 1</code>, <code>max = 255</code>).\n</li><li><code>DcmDspSecurityDelayTime :FloatParamDef</code> (Multiplizität 1..1, <code>min = 0</code>).\n</li><li><code>DcmDspSecurityDelayTimeOnBoot :FloatParamDef</code> (Multiplizität 1..1, <code>min = 0</code>).\n</li><li><code>DcmDspSecurityNumAttLock :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 0</code>, <code>max = 255</code>).\n</li><li><code>DcmDspSecuritySeedSize :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 1</code>, <code>max = 255</code>).\n</li><li><code>DcmDspSecurityKeySize :IntegerParamDef</code> (Multiplizität 1..1, <code>min = 1</code>, <code>max = 255</code>).\n</li><li><code>DcmDspSecurityADRSize :IntegerParamDef</code> (Multiplizität 0..1, <code>min = 1</code>, <code>max = 255</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsdiagramm ohne dynamische Interaktions- oder Ablaufbeschreibungen. Es spezifiziert die Struktur und Wertebereiche für die Parametrierung der Sicherheitszugriffsstufen (Security Levels), Fehlversuchszähler, Sperrzeiten (Delay Times) und Schlüssel-/Seed-Längen zur Generierungs- bzw. Kompilierzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist normativ für DCM-Konfigurationsgeneratoren und XML-/ARXML-Beschreibungen. Durch <code>DcmConfigSet</code> (<code>multipleConfigurationContainer = true</code>) wird die Einbettung in Post-Build- bzw. Mehrfachkonfigurationsszenarien unterstützt. Die Definition von <code>DcmDspSecurityLevel</code> schließt den Wert 0 durch <code>min = 1</code> explizit aus (entsprechend UDS, da Level 0 &#x27;locked&#x27; bedeutet und keine konfigurierbare Sicherheitsstufe darstellt). Multiplizitäten und Wertegrenzen sind verbindlich einzuhalten.</p>"}], "trans": [{"from": "FIG-3b479bd4856c1d4b", "to": "FIG-73b1140926bd8522", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Einführung des Containers <code>DcmConfigSet :ParamConfContainerDef</code> mit Multiplizität 0..1 und Attribut <code>multipleConfigurationContainer = true</code> zwischen <code>Dcm</code> und <code>DcmDsp</code>.\n</li><li>Die Kompositionsbeziehung vom Modul <code>Dcm</code> (<code>+container</code>) bindet nun an <code>DcmConfigSet</code>, und <code>DcmDsp</code> ist als <code>+subContainer</code> (Multiplizität 1..1) unter <code>DcmConfigSet</code> untergeordnet.\n</li><li><code>DcmDspSecurityLevel</code>: Minimalwert <code>min</code> wurde von 0 auf 1 geändert (<code>min = 1</code>).\n</li><li>Entfall des äußeren UML-Rahmens <code>class DcmDspSecurity</code>.\n</li></ul>"}]};
